Here is the commit message:
ACCUMULO-3583 Always return information about merges

Fix broken tests and ensure that TabletStateChangeIterator always returns
tablets for tables involved in merges.

Here is the root cause:
The bug was caused by the `TabletStateChangeIterator` not returning information about tablets involved in merges, leading to incomplete or incorrect state information during merge operations. This oversight could result in tests failing or the system behaving unexpectedly when handling tablet merges.

Here is the patch:

   @Override
   protected void consume() throws IOException {
     while (getSource().hasTop()) {
       Key k = getSource().getTopKey();
       Value v = getSource().getTopValue();

       if (onlineTables == null || current == null)
         return;

       TabletLocationState tls;
       try {
         tls = MetaDataTableScanner.createTabletLocationState(k, v);
         if (tls == null)
           return;
       } catch (BadLocationStateException e) {
         // maybe the master can do something with a tablet with bad/inconsistent state
         return;
       }
       // we always want data about merges
       MergeInfo merge = merges.get(tls.extent.getTableId());
-      if (merge != null && merge.getRange() != null && merge.getRange().overlaps(tls.extent)) {
+      if (merge != null) {
+        // could make this smarter by only returning if the tablet is involved in the merge
         return;
       }
+
       // is the table supposed to be online or offline?
       boolean shouldBeOnline = onlineTables.contains(tls.extent.getTableId().toString());

       switch (tls.getState(current)) {
         case ASSIGNED:
           // we always want data about assigned tablets
           return;
         case HOSTED:
           if (!shouldBeOnline)
             return;
           break;
         case ASSIGNED_TO_DEAD_SERVER:
           return;
         case UNASSIGNED:
           if (shouldBeOnline)
             return;
           break;
         default:
           throw new AssertionError("Inconceivable! The tablet is an unrecognized state: " + tls.getState(current));
       }
       // table is in the expected state so don't bother returning any information about it
       getSource().next();
     }
   }



